<?php require_once __DIR__ . '/includes/auth.php'; if (!empty($_SESSION['user'])) redirect($_SESSION['user']['role'] === 'hod' ? '/hod/dashboard.php' : '/lecturer/dashboard.php'); $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf(); $s=db()->prepare("SELECT u.*, d.name department_name FROM users u JOIN departments d ON d.id=u.department_id WHERE u.username=? AND u.status='active'"); $s->execute([trim($_POST['username'] ?? '')]); $u=$s->fetch(); if ($u && password_verify($_POST['password'] ?? '',$u['password'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role'],'department_id'=>$u['department_id']]; redirect($u['role']==='hod'?'/hod/dashboard.php':'/lecturer/dashboard.php'); } $error='Invalid username or password.'; } $title='Sign in'; require __DIR__.'/includes/header.php'; ?>
<section class="login-card"><img src="<?= baseUrl('/assets/images/lectra-logo.png') ?>" alt="Lectra Attendance Management System"><h2>Welcome back</h2><p>Sign in to manage attendance.</p><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Username<input required name="username" autofocus autocomplete="username"></label><label>Password<input required name="password" type="password" autocomplete="current-password"></label><button>Sign in</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>
